+function _adoRenderThreadSection(mapped, rootComment) {
+    var section = '### Thread ' + mapped.index;
+    if (mapped.path) {
+        section += ' — `' + mapped.path + '`';
+        if (mapped.line) section += ' line ' + mapped.line;
