        var statuses = ['fixed', 'closed', 'resolved', 'wontFix', 'byDesign'];
        for (var i = 0; i < statuses.length; i++) {
            var out = makeAdo(JSON.stringify({ value: [thread(1, statuses[i], { comments: [comment('x')] })] })).fetchDiscussions(5);
