+function _adoMapDiscussionThread(thread, index) {
+    if (thread.isDeleted === true) return null;
+    var rootComment = thread.comments && thread.comments[0];
+    var threadId = String(thread.id);
+    return {
+        index: index,
+        rootCommentId: threadId,
+        threadId: threadId,
