function makeGlobals(calls) {
    return {
        _parseJson: function(raw) { try { return JSON.parse(raw); } catch (e) { return raw; } },
        _toArray: function(v) { return Array.isArray(v) ? v : []; },
        ado_list_prs: function(a) { calls.push(['ado_list_prs', a]); return JSON.stringify({ value: [{ id: 1 }, { id: 2 }] }); },
        ado_get_pr_comments: function(a) { calls.push(['ado_get_pr_comments', a]); return JSON.stringify({ value: [
            { id: 10, isDeleted: false, status: 'active', threadContext: { filePath: '/x.js', rightFileStart: { line: 5 } }, comments: [{ content: '  hello  ', author: { displayName: 'Dev' }, publishedDate: '2026-02-03T00:00:00Z' }] },
            { id: 11, isDeleted: false, status: 'fixed', threadContext: {}, comments: [{ content: 'resolved c' }] },
            { id: 12, isDeleted: true, status: 'active', threadContext: {}, comments: [{ content: 'deleted' }] },
            { id: 13, isDeleted: false, status: 'active', threadContext: {}, comments: [{ content: '   ', author: { displayName: 'Ws' }, publishedDate: '2026-03-03T00:00:00Z' }] }
        ] }); },
        ado_list_pipeline_runs: function(a) { calls.push(['ado_list_pipeline_runs', a]); return JSON.stringify({ value: [
            { state: 'completed', result: 'succeeded' }, { state: 'completed', result: 'failed' }, { state: 'inProgress' }
        ] }); },
        ado_list_pipelines: function(a) { calls.push(['ado_list_pipelines', a]); return JSON.stringify({ value: [{ id: 42, name: 'CI' }] }); },
        ado_get_pr: function(a) { calls.push(['ado_get_pr', a]); return JSON.stringify({ id: 7 }); },
        ado_add_pr_comment: function(a) { calls.push(['ado_add_pr_comment', a]); return 'ok'; },
        ado_reply_to_pr_thread: function(a) { calls.push(['ado_reply_to_pr_thread', a]); return 'ok'; },
        ado_resolve_pr_thread: function(a) { calls.push(['ado_resolve_pr_thread', a]); return 'ok'; },
        ado_add_inline_comment: function(a) { calls.push(['ado_add_inline_comment', a]); return 'ok'; },
        ado_remove_pr_label: function(a) { calls.push(['ado_remove_pr_label', a]); return 'ok'; },
        ado_get_pipeline_logs: function(a) { calls.push(['ado_get_pipeline_logs', a]); return 'logs'; },
        ado_trigger_pipeline: function(a) { calls.push(['ado_trigger_pipeline', a]); return 'triggered'; },
        cli_execute_command: function(a) { calls.push(['cli_execute_command', a]); return 'https://dev.azure.com/org/proj/_git/repo\n'; },
        console: { warn: function(m) { calls.push(['console.warn', m]); } },
        JSON: JSON, Math: Math, Number: Number, String: String, Object: Object, Array: Array
    };
}

function loadProvider(file) {
    const fs = require('fs');
    let src = fs.readFileSync(file, 'utf8');
    const calls = [];
    const g = makeGlobals(calls);
    const keys = Object.keys(g);
    keys.push('require', 'module');
    const vals = Object.values(g);
    vals.push(function(name) { return {}; }, { exports: {} });
    const fn = new Function(...keys, src + '\nreturn _createAdoProvider("repo");');
    return { provider: fn(...vals), calls: calls };
}

const oldP = loadProvider('/tmp/scmcheck/scm_old.js');
const newP = loadProvider('/tmp/scmcheck/scm_new.js');

function runAll(p) {
    return {
        listPrs: p.provider.listPrs('open'),
        listPrsAll: p.provider.listPrs('closed'),
        getPr: p.provider.getPr(7),
        getPrComments: p.provider.getPrComments(7),
        fetchDiscussions: p.provider.fetchDiscussions(7),
        listWorkflowRuns: p.provider.listWorkflowRuns('succeeded', 'CI', 5),
        listWorkflowRunsFail: p.provider.listWorkflowRuns('failed', 'CI'),
        listWorkflowRunsNoStatus: p.provider.listWorkflowRuns(undefined, 42),
        triggerWorkflow: p.provider.triggerWorkflow('CI', 'refs/heads/main', { a: 1 }),
        triggerWorkflowNoPayload: p.provider.triggerWorkflow('CI'),
        replyToThread: p.provider.replyToThread(7, { threadId: 3 }, 'text'),
        replyToThreadNoId: p.provider.replyToThread(7, {}, 'text'),
        resolveThread: p.provider.resolveThread(7, { threadId: 3 }),
        resolveThreadNoId: p.provider.resolveThread(7, {}),
        addInlineComment: p.provider.addInlineComment(7, '/f.js', 3, 'txt', 2, 'RIGHT'),
        removeLabel: p.provider.removeLabel(7, 'lbl', 'lid'),
        removeLabelNoId: p.provider.removeLabel(7, 'lbl'),
        getJobLogs: p.provider.getJobLogs('12', '20'),
        getJobLogsNoTail: p.provider.getJobLogs('12'),
        getRemoteRepoInfo: p.provider.getRemoteRepoInfo()
    };
}

const oldOut = runAll(oldP);
const newOut = runAll(newP);

let fail = 0;
for (const k of Object.keys(oldOut)) {
    const o = JSON.stringify(oldOut[k]);
    const n = JSON.stringify(newOut[k]);
    const same = o === n;
    if (!same) fail++;
    console.log((same ? 'SAME  ' : 'DIFF  ') + k);
    if (!same) {
        console.log('  old: ' + o);
        console.log('  new: ' + n);
    }
}
const oc = JSON.stringify(oldP.calls), nc = JSON.stringify(newP.calls);
console.log('side-effect call sequences equal:', oc === nc);
if (oc !== nc) {
    for (let i = 0; i < Math.max(oc.length, nc.length); i++) if (oc[i] !== nc[i]) { console.log('calls diff at', i, oc.slice(i-40, i+60), 'vs', nc.slice(i-40, i+60)); break; }
}
console.log('TOTAL DIFFS:', fail);
