        assert.contains(out.markdown, '## Review Threads\n\n');
        assert.contains(out.markdown, '### Thread 1 — `/src/a.js` line 12\n\n');
        assert.contains(out.markdown, '**Dev User** (2026-01-02):\nPlease fix  <b>this</b>\n\n---\n\n');
